using FluentAssertions; using Xunit;
namespace Sigov.IntegrationTests; public sealed class AgroParte5ModuleTests{private static readonly string Migration=File.ReadAllText(Path.Combine(FindRepositoryRoot(),"database","postgres","migrations","20260608130000_agro_estradas_feiras_agroindustrias.sql")); [Theory] [InlineData("sigov.agro_estrada_vicinal")] [InlineData("sigov.agro_ponto_critico_rural")] [InlineData("sigov.agro_ocorrencia_rural")] [InlineData("sigov.agro_manutencao_rural")] [InlineData("sigov.agro_feira")] [InlineData("sigov.agro_feirante")] [InlineData("sigov.agro_banca_feira")] [InlineData("sigov.agro_autorizacao_feira")] [InlineData("sigov.agro_agroindustria")] [InlineData("sigov.agro_inspecao_municipal")] [InlineData("sigov.agro_compra_agricultura_familiar")] public void Migration_cria_tabelas_da_parte_5_no_schema_sigov(string table)=>Migration.Should().Contain(table); [Fact] public void Migration_nao_cria_schema_agro()=>Migration.ToLowerInvariant().Should().NotContain("create schema "+"agro"); [Fact] public void Tabelas_possuem_tenant_id()=>Migration.Should().Contain("tenant_id bigint not null references sigov.tenant(id)"); [Fact] public void Dashboard_retorna_indicadores_parte_5(){Migration.Should().Contain("total_estradas_vicinais").And.Contain("compras_agricultura_familiar_mes").And.Contain("valor_comprado_mes");} [Fact] public void Geo_e_tenant_isolation_estao_presentes(){Migration.Should().Contain("agro_geo_camada").And.Contain("idx_agro_estrada_tenant_codigo"); File.ReadAllText(Path.Combine(FindRepositoryRoot(),"src","Sigov.Infrastructure","Agro","Repositories","AgroInfraestruturaRuralRepository.cs")).Should().Contain("tenant_id=@t").And.Contain("entidade_id=@e");} static string FindRepositoryRoot(){var d=new DirectoryInfo(AppContext.BaseDirectory); while(d is not null&&!File.Exists(Path.Combine(d.FullName,"sigov.sln")))d=d.Parent; return d?.FullName??throw new InvalidOperationException("Raiz do repositório não encontrada.");}}
